#!/usr/bin/env bash
# Generated by prereg_windows.py -- runs every pre-registered window.
# Run from goldbach-gaps/:   ENGINE_DIR=engine THREADS=12 prereg/run_grid.sh
# Results go to ./runs/. Windows already present in a minpstats file are skipped,
# so the script can be re-run after an interruption.
# Build once per gap, from goldbach-gaps/ (plain build is fine: the minimal-partner scan dominates):
#   g++ -O3 -march=native -fopenmp -std=c++17 -DSIMD_AVX2 -DGAP=6 engine/goldbach_v6_4_gap.cpp -o engine/gb_gap6
#   g++ -O3 -march=native -fopenmp -std=c++17 -DSIMD_AVX2 -DGAP=30 engine/goldbach_v6_4_gap.cpp -o engine/gb_gap30
#   g++ -O3 -march=native -fopenmp -std=c++17 -DSIMD_AVX2 -DGAP=210 engine/goldbach_v6_4_gap.cpp -o engine/gb_gap210
#   g++ -O3 -march=native -fopenmp -std=c++17 -DSIMD_AVX2 -DGAP=2310 engine/goldbach_v6_4_gap.cpp -o engine/gb_gap2310
#   g++ -O3 -march=native -fopenmp -std=c++17 -DSIMD_AVX2 -DGAP=30030 engine/goldbach_v6_4_gap.cpp -o engine/gb_gap30030
#   g++ -O3 -march=native -fopenmp -std=c++17 -DSIMD_AVX2 -DGAP=510510 engine/goldbach_v6_4_gap.cpp -o engine/gb_gap510510
set -euo pipefail
THREADS=${THREADS:-12}
ENGINE_DIR=$(cd "${ENGINE_DIR:-engine}" && pwd)
mkdir -p runs && cd runs
[ -n "$(awk -F, '$2==1000000000 && $3==1000199998' goldbach_gap6_minpstats.csv 2>/dev/null)" ] || "$ENGINE_DIR/gb_gap6" 1000000000 1000199998 11 $THREADS 1000000 0 1024 --minp-per-window=100000 --minp-limit=0 > log_gap6_1000000000.txt 2>&1
